import { onMount, onCleanup, createEffect } from "solid-js";
import { mountSpiderMusicPlayer, type SpiderMusicPlayerOptions } from "../../components/spider-music-player/SpiderMusicPlayerEngine.js";
import type { MotionController } from "../../components/spider-music-player/motion-runtime";

export function SpiderMusicPlayer(props: { options?: SpiderMusicPlayerOptions; class?: string }) {
  let host!: HTMLDivElement;
  let controller: MotionController | undefined;
  onMount(() => { controller = mountSpiderMusicPlayer(host, props.options); });
  createEffect(() => { const options = props.options; controller?.update(options ?? {}); });
  onCleanup(() => controller?.destroy());
  return <div ref={host} class={props.class} data-motion-component="spider-music-player" />;
}

